package com.example.salarygrows;
import android.app.*;import android.appwidget.*;import android.content.*;import android.widget.*;import java.time.*;import java.text.*;import java.util.*;
public class SalaryWidget extends AppWidgetProvider {
 public static void refresh(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);int[] ids=m.getAppWidgetIds(new ComponentName(c,SalaryWidget.class));if(ids.length>0)render(c,m,ids);}
 static void render(Context c,AppWidgetManager m,int[] ids){SharedPreferences p=c.getSharedPreferences("salary",Context.MODE_PRIVATE);boolean net=p.getBoolean("net_mode",true);long target=p.getLong(net?"net":"gross",net?2500000:2800000);LocalDateTime n=LocalDateTime.now();int days=YearMonth.from(n).lengthOfMonth();double f=((n.getDayOfMonth()-1)*86400d+n.getHour()*3600d+n.getMinute()*60d+n.getSecond())/(days*86400d);for(int id:ids){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.salary_widget);v.setTextViewText(R.id.title,"월급이 자란다 · "+(net?"세후":"세전"));v.setTextViewText(R.id.amount,NumberFormat.getIntegerInstance(Locale.KOREA).format((long)(target*f))+"원");v.setTextViewText(R.id.progress_text,String.format(Locale.KOREA,"달성률 %.2f%%",f*100));v.setProgressBar(R.id.progress,10000,(int)Math.round(f*10000),false);PendingIntent pi=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(R.id.title,pi);v.setOnClickPendingIntent(R.id.amount,pi);m.updateAppWidget(id,v);}}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){render(c,m,ids);}
}